def transform(grid):
    from collections import Counter, deque

    if not grid or not grid[0]:
        return []

    rows = len(grid)
    cols = len(grid[0])

    # Find background color (most common)
    counts = Counter()
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] += 1
    background = counts.most_common(1)[0][0]

    # Visited array for connected components
    visited = [[False]*cols for _ in range(rows)]

    output = [[background]*cols for _ in range(rows)]

    # Find connected components for each color
    for color in set(grid[r][c] for r in range(rows) for c in range(cols)):
        if color == background:
            continue

        # BFS to find connected component
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color and not visited[r][c]:
                    component = []
                    queue = deque([(r, c)])
                    visited[r][c] = True

                    while queue:
                        curr_r, curr_c = queue.popleft()
                        component.append((curr_r, curr_c))

                        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if not visited[nr][nc] and grid[nr][nc] == color:
                                    visited[nr][nc] = True
                                    queue.append((nr, nc))

                    # Compute bounding box
                    if len(component) > 4:  # Only substantial components
                        min_r = min(p[0] for p in component)
                        max_r = max(p[0] for p in component)
                        min_c = min(p[1] for p in component)
                        max_c = max(p[1] for p in component)

                        area = (max_r - min_r + 1) * (max_c - min_c + 1)
                        fill_ratio = len(component) / area

                        # If fill ratio > 50%, fill entire bounding box
                        if fill_ratio > 0.5:
                            for r in range(min_r, max_r + 1):
                                for c in range(min_c, max_c + 1):
                                    output[r][c] = color

    return output
